from typing import List

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        # Using brute force to check all non-empty subsets
        n = len(nums)
        max_strength = float('-inf')

        # Iterate through all non-empty subsets (from 1 to 2^n - 1)
        for i in range(1, 2**n):
            strength = 1
            for j in range(n):
                if (i & (1 << j)) != 0:
                    strength *= nums[j]

            max_strength = max(max_strength, strength)

        return max_strength

