class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i] represents maximum jumps to reach index i
        dp = [-1] * n
        dp[0] = 0  # Starting position requires 0 jumps

        for i in range(n):
            # Skip if we can't reach this position
            if dp[i] == -1:
                continue

            # Try all possible jumps from position i to position j
            for j in range(i + 1, n):
                # Check if we can jump from i to j
                # This means nums[i] - target <= nums[j] <= nums[i] + target
                if nums[i] - target <= nums[j] <= nums[i] + target:
                    # Update maximum jumps needed to reach j
                    if dp[j] == -1:
                        dp[j] = dp[i] + 1
                    else:
                        dp[j] = max(dp[j], dp[i] + 1)

        return dp[n - 1]

