    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        # Hashmap to store frequency of coordinates seen so far
        coord_map = {}
        result = 0

        # Iterate through all coordinates
        for x, y in coordinates:
            # For each possible split of k into d and (k-d)
            # where x1 XOR x2 = d and y1 XOR y2 = k-d
            for d in range(k + 1):
                # If x1 XOR x2 = d, then x2 = x1 XOR d
                target_x = x ^ d
                # If y1 XOR y2 = k-d, then y2 = y1 XOR (k-d)
                target_y = y ^ (k - d)

                # Check if this pair (target_x, target_y) has been seen before
                if (target_x, target_y) in coord_map:
                    result += coord_map[(target_x, target_y)]

            # Add current coordinate to the map
            if (x, y) not in coord_map:
                coord_map[(x, y)] = 0
            coord_map[(x, y)] += 1

