        # We can make 2^(segments-1) good partitions 
        # (as there's 1 way when segments=1, 2^(n-1) when segments=n)
        if segments == 0:
            return 1
        return pow(2, segments - 1, MOD)

class Solution:
    def returnToBoundaryCount(self, nums: List[int]) -> int:
        position = 0
        count = 0

        for num in nums:
            # Move the ant by num units
            position += num

            # Check if ant is back at boundary (position 0)
            if position == 0:
                count += 1

        return count

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n < 2:
                return False
            if n == 2:
                return True
            if n % 2 == 0:
                return False

            # Check odd divisors up to sqrt(n)
            for i in range(3, int(n**0.5) + 1, 2):
                if n % i == 0:
                    return False
            return True

        # Find first and last prime indices
        first_prime_idx = -1
        last_prime_idx = -1

        for i in range(len(nums)):
            if is_prime(nums[i]):
                if first_prime_idx == -1:
                    first_prime_idx = i
                last_prime_idx = i

        # Return the maximum distance
        return last_prime_idx - first_prime_idx

class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # Check all four possible 2x2 squares
        squares = [
            [(0, 0), (1, 1)],  # top-left
            [(0, 1), (1, 2)],  # top-right  
            [(1, 0), (2, 1)],  # bottom-left
            [(1, 1), (2, 2)]   # bottom-right
        ]

        def is_valid_square(r1, c1, r2, c2):
            b_count = 0
            w_count = 0
            # Count colors in 2x2 square
            for i in range(r1, r2 + 1):
                for j in range(c1, c2 + 1):
                    if grid[i][j] == 'B':
                        b_count += 1
                    else:
                        w_count += 1
            # We can make square all same color if there are 3 or more of one color
            # (then we can make 1 change to get 4 of that color)
            # Or if we have all 4 the same already
            return b_count >= 3 or w_count >= 3

        for (r1, c1), (r2, c2) in squares:
            if is_valid_square(r1, c1, r2, c2):
                return True

        return False

def solve():
    s = input().strip()

    # Use a stack-like approach to simulate the removal
    # The key is that we want to remove longest possible valid patterns
    # We'll use a list to simulate stack operations efficiently

    stack = []

    # Process each character of the string
    for ch in s:
        if ch == '(':
            # Add the open parenthesis to stack
            stack.append(ch)
        elif ch == ')':
            # Try to remove a valid pattern (letters) from the stack
            # Find the most recent '(' in the stack  
            open_pos = -1
            for i in range(len(stack) - 1, -1, -1):
                if stack[i] == '(':
                    open_pos = i
                    break

            if open_pos != -1:
                # Found matching open parenthesis
                # Remove the substack from open_pos to current position 
                # That is from '(' onwards to the ')' which would have been added by this iteration
                # But we also need to remove the ')' itself 
                # Actually this logic needs more precision
                stack = stack[:open_pos]
            else:
                # No matching open parenthesis, so add this closing bracket
                stack.append(ch)
        else:
            # Normal letter character
            stack.append(ch)

    return ''.join(stack)

