def is_subsequence(s, t):
    """Check if t is subsequence of s"""
    if len(t) == 0:
        return True
    if len(s) == 0:
        return False

    i = 0  # index for t
    j = 0  # index for s

    while i < len(t) and j < len(s):
        if s[j] == t[i]:
            i += 1
        j += 1

    return i == len(t)

